def transform(grid):
    out=[r[:] for r in grid]
    cycle=[1,3,5,7,9]
    for i,row in enumerate(grid):
        for j,value in enumerate(row):
            if value != 0:
                continue
            if i < 2:
                out[i][j]=1
            elif j < 3:
                out[i][j]=[1,1,4][j]
            elif i == 2:
                out[i][j]=4
            else:
                anchors=[k for k,x in enumerate(row) if k>=3 and x in cycle]
                k=min(anchors,key=lambda k:abs(k-j))
                out[i][j]=cycle[(cycle.index(row[k])+j-k)%5]
    return out
